// Period: load 2 days more history than the dead-stock threshold
const S = $('Sozlamalar').first().json;
const OLIK = Number(S.olik_kun) || 30;
const TZ = 5 * 3600 * 1000;
const fmt = ms => new Date(ms).toISOString().slice(0, 19).replace('T', ' ');
const now = Date.now();
const tk = new Date(now + TZ);
const todayMid = Date.UTC(tk.getUTCFullYear(), tk.getUTCMonth(), tk.getUTCDate()) - TZ;
const from = fmt(todayMid - (OLIK + 2) * 864e5);
return [{ json: { sales_from: from, purchase_from: from, to: fmt(now) } }];

// Read page count from the first page and build the list of all page URLs
const S = $('Sozlamalar').first().json, D = $('Davr').first().json;
const host = String(S.host).replace(/^https?:\/\//, '').replace(/\/+$/, '');
const first = $input.first().json;
const last = Math.max(1, Math.min(Number(first.last_page) || 1, 500));
const base = `https://${host}/api/integration/document/shipment/list`;
const q = p => `per_page=100&page=${p}&period%5Bfrom%5D=${encodeURIComponent(D.sales_from)}&period%5Bto%5D=${encodeURIComponent(D.to)}`;
const items = [];
for (let p = 1; p <= last; p++) items.push({ json: { url: `${base}?${q(p)}`, page: p, last_page: last, total: first.total } });
return items;

// Read page count from the first page and build the list of all page URLs
const S = $('Sozlamalar').first().json, D = $('Davr').first().json;
const host = String(S.host).replace(/^https?:\/\//, '').replace(/\/+$/, '');
const first = $input.first().json;
const last = Math.max(1, Math.min(Number(first.last_page) || 1, 500));
const base = `https://${host}/api/integration/document/purchase/list`;
const q = p => `per_page=100&page=${p}&period%5Bfrom%5D=${encodeURIComponent(D.purchase_from)}&period%5Bto%5D=${encodeURIComponent(D.to)}`;
const items = [];
for (let p = 1; p <= last; p++) items.push({ json: { url: `${base}?${q(p)}`, page: p, last_page: last, total: first.total } });
return items;

// First stock page for every own warehouse
const S = $('Sozlamalar').first().json;
const host = String(S.host).replace(/^https?:\/\//, '').replace(/\/+$/, '');
const OWN = String(S.oz_omborlar).split(/[\s,]+/).filter(Boolean);
return OWN.map(w => ({ json: { wid: Number(w),
  url: `https://${host}/api/integration/document/stock/selection?warehouse_id=${w}&only_available=1&per_page=100&page=1` } }));

// All stock pages for every warehouse
const reqs = $('Zaxira sorovlari').all();
const out = [];
$input.all().forEach((r, i) => {
  const q = reqs[i].json;
  const last = Math.max(1, Math.min(Number(r.json.last_page) || 1, 300));
  for (let p = 1; p <= last; p++)
    out.push({ json: { wid: q.wid, total: Number(r.json.total) || null, url: q.url.replace(/page=1$/, 'page=' + p) } });
});
return out;

// ===== DEAD STOCK: daily check + weekly full list =====
const S = $('Sozlamalar').first().json;
const KOCHA = Number(S.kocha_ombor_id);
const OWN = String(S.oz_omborlar).split(/[\s,]+/).filter(Boolean).map(Number);
const OLIK = Number(S.olik_kun) || 30;
const HAFTA = S.toliq_hafta_kuni === undefined || S.toliq_hafta_kuni === '' ? 1 : Number(S.toliq_hafta_kuni); // 1 = Monday
const TZ = 5 * 3600 * 1000;
const dayKey = iso => new Date(new Date(iso).getTime() + TZ).toISOString().slice(0, 10);
const todayKey = dayKey(new Date().toISOString());
const diff = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 864e5);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = (v, d = 0) => { const [a, b] = (Math.round(Number(v) * 10 ** d) / 10 ** d).toFixed(d).split('.'); return a.replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + (b ? '.' + b : ''); };
const qn = v => num(v, 1).replace(/\.0$/, '');
const hd = k => k.slice(8, 10) + '.' + k.slice(5, 7) + '.' + k.slice(0, 4), dm = k => k.slice(8, 10) + '.' + k.slice(5, 7);
const sgn = (v, suf) => (v > 0 ? '+' : v < 0 ? '−' : '') + num(Math.abs(v)) + (suf || '');
let rate = null;
try { const r = ($('Kurs').first().json.data || []).map(x => Number(x.exchange_rate)).filter(x => x > 1000).sort((a, b) => a - b); if (r.length) rate = r[Math.floor(r.length / 2)]; } catch (e) { }
const uzs = (v, cur) => cur === 'USD' ? (rate ? v * rate : null) : v;
const whName = {};
for (const nm of ['Zakuplar', 'Sotuvlar']) { try { for (const pg of $(nm).all()) for (const d of (pg.json.data || [])) for (const l of (d.purchase_details || d.shipment_details || [])) if (l.warehouse) whName[l.warehouse.id] = l.warehouse.name; } catch (e) { } }

// ---- 1. last sale and last arrival per product ----
const lastSale = {}; let minSale = todayKey; const seenS = new Set();
for (const page of $('Sotuvlar').all()) for (const doc of (page.json.data || [])) {
  if (seenS.has(doc.id)) continue; seenS.add(doc.id);
  if (![23, 24].includes(Number(doc.status))) continue;
  const k = dayKey(doc.date); if (k < minSale) minSale = k;
  for (const l of (doc.shipment_details || [])) if (!lastSale[l.product_id] || k > lastSale[l.product_id]) lastSale[l.product_id] = k;
}
const windowDays = diff(todayKey, minSale);
const lastBuy = {}; const seenP = new Set();
for (const page of $('Zakuplar').all()) for (const doc of (page.json.data || [])) {
  if (seenP.has(doc.id)) continue; seenP.add(doc.id);
  if (Number(doc.status) !== 13) continue;
  const k = dayKey(doc.date);
  for (const l of (doc.purchase_details || [])) if (Number(l.warehouse_id) !== KOCHA && (!lastBuy[l.product_id] || k > lastBuy[l.product_id])) lastBuy[l.product_id] = k;
}

// ---- 2. stock on hand ----
const st = {}; const reqs = $('Zaxira sahifalari').all(); const seen = new Set(); const whSeen = {}, whTotal = {};
$('Zaxiralar').all().forEach((r, i) => {
  const q = reqs[i] && reqs[i].json; if (!q) return;
  whTotal[q.wid] = q.total;
  for (const x of (r.json.data || [])) {
    const key = q.wid + ':' + x.id; if (seen.has(key)) continue; seen.add(key); whSeen[q.wid] = (whSeen[q.wid] || 0) + 1;
    const a = Number(x.available || 0); if (a <= 0) continue;
    const p = (st[x.id] ||= { id: x.id, name: x.name, unit: x.storage_unit ? x.storage_unit.short_name : '', total: 0, parts: [], price: null });
    p.total += a; p.parts.push([q.wid, a]);
    const lp = x.last_purchase_price;
    if (lp && lp.price != null && p.price == null) p.price = uzs(Number(lp.price), lp.currency ? lp.currency.code : 'UZS');
  }
});
const stockFull = OWN.every(w => !whTotal[w] || (whSeen[w] || 0) >= whTotal[w] * 0.98);
const dataOk = windowDays >= OLIK && stockFull;

// ---- 3. dead items ----
const dead = []; let noPrice = 0;
for (const p of Object.values(st)) {
  const ls = lastSale[p.id], since = ls ? diff(todayKey, ls) : null;
  if (since != null && since < OLIK) continue;
  if (lastBuy[p.id] && diff(todayKey, lastBuy[p.id]) < OLIK) continue;       // arrived recently
  const value = p.price != null ? p.price * p.total : null; if (value == null) noPrice++;
  dead.push({ ...p, since, value, buy: lastBuy[p.id] || null });
}
dead.sort((a, b) => (b.value || 0) - (a.value || 0));
const total = dead.reduce((s, d) => s + (d.value || 0), 0);

// ---- 4. compare with yesterday ----
const sd = $getWorkflowStaticData('global');
const prev = sd.prev && sd.prev.date !== todayKey ? sd.prev : (sd.prev2 || null);   // re-run today — compare with previous day
const nowIds = new Set(dead.map(d => String(d.id)));
let left = [], added = [];
if (prev) {
  left = Object.entries(prev.items).filter(([id]) => !nowIds.has(id)).map(([id, v]) => {
    const s = st[id]; const ls = lastSale[id];
    const why = !s ? 'qoldiq tugadi' : (ls && diff(todayKey, ls) < OLIK ? 'sotildi (' + dm(ls) + ')' : (lastBuy[id] && diff(todayKey, lastBuy[id]) < OLIK ? 'yangi kirim keldi' : 'chiqdi'));
    return { id, name: v[0], value: v[1], why };
  }).sort((a, b) => b.value - a.value);
  added = dead.filter(d => !(String(d.id) in prev.items));
}

// ---- 5. messages ----
let manual = false;
try { manual = $("Qo'lda sinash").isExecuted; } catch (e) { }
try { if ($execution.mode === 'test') manual = true; } catch (e) { }   // started manually (Execute)
const wd = new Date(Date.now() + TZ).getUTCDay();
const full = manual || HAFTA === 0 || wd === HAFTA;
const blocks = []; let rows = [];
if (!dataOk) {
  blocks.push(`🧊 <b>O'LIK TOVAR — ${hd(todayKey)}</b>\n⚠️ <b>Ma'lumot to'liq yuklanmadi</b> (sotuv tarixi: ${windowDays} kun, qoldiq: ${stockFull ? "to'liq" : 'chala'}). Bugungi hisob tashlab ketildi.`);
} else {
  let h = `🧊 <b>O'LIK TOVAR — ${hd(todayKey)}</b>\n🏢 ${esc(S.filial_nomi)}\n\n`;
  h += `<b>${OLIK}+ kun sotilmagan</b> qoldiq: <b>${num(dead.length)}</b> ta tovar\nMuzlagan pul: <b>~${num(total)} so'm</b>\n`;
  if (prev) {
    const dc = dead.length - prev.count, ds = total - prev.total;
    const ic = ds < -1 ? '⬇️ kamaydi' : ds > 1 ? '⬆️ ko\'paydi' : '➡️ o\'zgarmadi';
    h += `\n<b>${dm(prev.date)} ga nisbatan: ${ic}</b>\n• Tovarlar: ${sgn(dc, ' ta')}\n• Summa: <b>${sgn(ds, " so'm")}</b>\n`;
  } else h += `\n<i>Bu birinchi hisobot — ertadan boshlab kechagi kun bilan solishtiriladi.</i>\n`;
  if (full && sd.week && sd.week.date !== todayKey) h += `\n<b>O'tgan haftaga (${dm(sd.week.date)}) nisbatan:</b> ${sgn(dead.length - sd.week.count, ' ta')} · ${sgn(total - sd.week.total, " so'm")}\n`;
  if (noPrice) h += `\n<i>Narxi noma'lum: ${noPrice} ta — summaga kirmadi</i>`;
  blocks.push(h.trim());

  if (prev && left.length) blocks.push(`✅ <b>Ro'yxatdan chiqdi: ${left.length} ta</b>\n` +
    left.slice(0, 10).map(x => `• ${esc(x.name)} — ${num(x.value)} so'm · <i>${x.why}</i>`).join('\n') + (left.length > 10 ? `\n… va yana ${left.length - 10} ta` : ''));
  if (prev && added.length) blocks.push(`🆕 <b>Ro'yxatga qo'shildi: ${added.length} ta</b>\n` +
    added.slice(0, 10).map(x => `• ${esc(x.name)} — ${x.value != null ? num(x.value) + " so'm" : 'narxi noma\'lum'} · ${qn(x.total)} ${esc(x.unit)}`).join('\n') + (added.length > 10 ? `\n… va yana ${added.length - 10} ta` : ''));

  if (full) {
    blocks.push(`📋 <b>ENG KO'P PUL BOG'LAGAN 10 TA TOVAR</b> <i>(to'liq ro'yxat — ilovadagi Excel faylda)</i>`);
    dead.slice(0, 10).forEach((d, i) => {
      let t = `${i + 1}. <b>${esc(d.name)}</b> <code>ID ${d.id}</code>\n`;
      t += `   Qoldiq: <b>${qn(d.total)} ${esc(d.unit)}</b> (${d.parts.map(([w, a]) => esc(whName[w] || w) + (d.parts.length > 1 ? ' ' + qn(a) : '')).join(', ')})`;
      t += d.value != null ? ` · <b>~${num(d.value)} so'm</b>\n` : ` · narxi noma'lum\n`;
      t += `   Oxirgi sotuv: ${d.since != null ? d.since + ' kun oldin' : windowDays + '+ kun oldin'} · oxirgi kirim: ${d.buy ? dm(d.buy) : OLIK + '+ kun oldin'}`;
      blocks.push(t);
    });
    // full list for Excel
    rows = dead.map((d, i) => ({
      '№': i + 1, 'ID': d.id, 'Tovar nomi': d.name, 'Qoldiq': d.total, 'Birlik': d.unit,
      'Omborlar': d.parts.map(([w, a]) => (whName[w] || w) + ': ' + a).join('; '),
      "Kelish narxi (so'm)": d.price != null ? Math.round(d.price) : '',
      "Muzlagan summa (so'm)": d.value != null ? Math.round(d.value) : '',
      'Oxirgi sotuv (kun oldin)': d.since != null ? d.since : windowDays + '+',
      'Oxirgi kirim': d.buy ? hd(d.buy) : OLIK + '+ kun oldin',
    }));
  }
  // save snapshot (only when data is complete)
  const snap = { date: todayKey, count: dead.length, total, items: Object.fromEntries(dead.map(d => [String(d.id), [d.name, Math.round(d.value || 0)]])) };
  if (sd.prev && sd.prev.date !== todayKey) sd.prev2 = sd.prev;
  sd.prev = snap;
  if (wd === HAFTA && (!sd.week || sd.week.date !== todayKey)) sd.week = { date: todayKey, count: dead.length, total };
}
const msgs = []; let cur = '';
for (const b of blocks) { if (cur && (cur + '\n\n' + b).length > 3800) { msgs.push(cur); cur = b.slice(0, 3800); } else cur = cur ? cur + '\n\n' + b : b; }
if (cur) msgs.push(cur);
const out = msgs.map(text => ({ json: { text } }));
if (out.length) { out[0].json.rows = rows; out[0].json.fayl = `olik_tovar_${todayKey}.xlsx`; out[0].json.izoh = `🧊 O'lik tovar — to'liq ro'yxat (${num(dead.length)} ta, ~${num(total)} so'm) · ${hd(todayKey)}`; }
return out;

// Excel rows: only on full-report day (Monday or manual run)
const f = $('Olik tahlili').first().json;
return (f.rows || []).map(r => ({ json: r }));
